const { exec } = require("child_process");
const fs = require("fs").promises;
const path = require("path");

const workspaceDir = path.resolve(__dirname, "..");
const lockFile = path.join(workspaceDir, ".next", "dev", "lock");
const cacheDir = path.join(workspaceDir, ".next", "dev", "cache");

const execPromise = (command) => new Promise((resolve) => {
  exec(command, (err, stdout, stderr) => {
    resolve({ err, stdout, stderr });
  });
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function getPidsOnPort(port) {
  const pids = new Set();
  try {
    if (process.platform === "win32") {
      const { stdout } = await execPromise(`netstat -ano`);
      const lines = stdout.split("\n");
      for (const line of lines) {
        if (line.includes(`:${port}`) && line.includes("LISTENING")) {
          const parts = line.trim().split(/\s+/);
          const pidStr = parts[parts.length - 1];
          const pid = parseInt(pidStr, 10);
          if (!isNaN(pid) && pid > 0) {
            pids.add(pid);
          }
        }
      }
    } else {
      const { stdout } = await execPromise(`lsof -t -i :${port}`);
      if (stdout) {
        stdout.split("\n").forEach((line) => {
          const pid = parseInt(line.trim(), 10);
          if (!isNaN(pid) && pid > 0) {
            pids.add(pid);
          }
        });
      }
    }
  } catch {
    // Ignore execution failures if port is unoccupied
  }
  return Array.from(pids);
}

async function getWorkspaceDevServerPids(currentPid, parentPid, workspaceDir, workspaceName) {
  const devServerPids = new Set();
  try {
    if (process.platform === "win32") {
      const cmd = `powershell -NoProfile -Command "Get-CimInstance Win32_Process | Select-Object ProcessId, CommandLine | ConvertTo-Json -Compress"`;
      const { stdout } = await execPromise(cmd);
      if (stdout) {
        try {
          let processes = JSON.parse(stdout.trim());
          if (!Array.isArray(processes)) {
            processes = [processes];
          }
          for (const proc of processes) {
            if (!proc || !proc.CommandLine) continue;
            const pid = proc.ProcessId;
            const command = proc.CommandLine;
            if (pid === currentPid || pid === parentPid) continue;
            const isNextProcess = command.includes("next-server") || command.includes("next dev") || command.includes(".bin\\next") || command.includes("next-dev");
            const isThisWorkspace = command.includes(workspaceName) || command.includes(workspaceDir);
            if (isNextProcess && isThisWorkspace) {
              devServerPids.add(pid);
            }
          }
        } catch {
          const { stdout: wmicOut } = await execPromise("wmic process get processid,commandline");
          const lines = wmicOut.split("\n");
          for (const line of lines) {
            if (line.includes("next dev") || line.includes("next-server")) {
              const parts = line.trim().split(/\s+/);
              const pid = parseInt(parts[parts.length - 1], 10);
              if (!isNaN(pid) && pid !== currentPid && pid !== parentPid) {
                devServerPids.add(pid);
              }
            }
          }
        }
      }
    } else {
      const { stdout } = await execPromise("ps -ax -o pid,command");
      if (stdout) {
        const lines = stdout.split("\n");
        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed) continue;
          const match = trimmed.match(/^(\d+)\s+(.+)$/);
          if (!match) continue;
          const pid = parseInt(match[1], 10);
          const command = match[2];
          if (pid === currentPid || pid === parentPid) continue;
          const isNextProcess = command.includes("next-server") || command.includes("next dev") || command.includes(".bin/next");
          const isThisWorkspace = command.includes(workspaceName) || command.includes(workspaceDir);
          if (isNextProcess && isThisWorkspace) {
            devServerPids.add(pid);
          }
        }
      }
    }
  } catch (err) {
    console.log(`• Error auditing running processes: ${err.message}`);
  }
  return Array.from(devServerPids);
}

async function gracefulKill(pid) {
  try {
    try {
      process.kill(pid, 0);
    } catch {
      return true; // Already exited
    }

    console.log(`• Terminating process PID ${pid} gracefully (SIGTERM)...`);
    if (process.platform === "win32") {
      await execPromise(`taskkill /PID ${pid}`);
    } else {
      process.kill(pid, "SIGTERM");
    }

    for (let i = 0; i < 10; i++) {
      await sleep(150);
      try {
        process.kill(pid, 0);
      } catch {
        console.log(`✓ Process PID ${pid} exited.`);
        return true;
      }
    }

    console.log(`⚠ PID ${pid} failed to exit. Force killing (SIGKILL)...`);
    if (process.platform === "win32") {
      await execPromise(`taskkill /F /PID ${pid}`);
    } else {
      process.kill(pid, "SIGKILL");
    }
    return true;
  } catch (err) {
    console.log(`• Failed to cleanly terminate PID ${pid}: ${err.message}`);
    return false;
  }
}

async function main() {
  console.log("=== Asynchronous Pre-dev Check ===");
  const currentPid = process.pid;
  const parentPid = process.ppid;
  const workspaceName = path.basename(workspaceDir);

  let isUncleanShutdown = false;
  let lockExists = false;

  try {
    await fs.access(lockFile);
    lockExists = true;
  } catch {
    // Lock file not present
  }

  // 1. Audit and terminate concurrent Next.js dev server processes
  const devServerPids = await getWorkspaceDevServerPids(currentPid, parentPid, workspaceDir, workspaceName);
  let killedCount = 0;

  if (devServerPids.length > 0) {
    console.log(`• Detected ${devServerPids.length} active dev server process(es). Cleaning up...`);
    isUncleanShutdown = true;
    for (const pid of devServerPids) {
      const ok = await gracefulKill(pid);
      if (ok) killedCount++;
    }
  }

  // 2. Audit processes occupying port 3000
  const portPids = await getPidsOnPort(3000);
  if (portPids.length > 0) {
    console.log(`• Port 3000 occupied by PID(s): ${portPids.join(", ")}. Terminating...`);
    isUncleanShutdown = true;
    for (const pid of portPids) {
      if (pid === currentPid || pid === parentPid) continue;
      await gracefulKill(pid);
    }
  } else {
    console.log("✓ Port 3000 is clear");
  }

  // 3. Handle Lock File and automatic recovery
  if (lockExists) {
    try {
      await fs.unlink(lockFile);
      console.log("✓ Removed stale .next/dev/lock file");
      isUncleanShutdown = true;
    } catch {
      // Lock might have been cleaned up by terminated processes
    }
  }

  // 4. Recover Turbopack cache if unclean shutdown detected
  if (isUncleanShutdown) {
    console.log("⚠ Unclean shutdown detected. Rebuilding Turbopack cache directory...");
    try {
      await fs.rm(cacheDir, { recursive: true, force: true });
      console.log("✓ Turbopack cache cleared at .next/dev/cache");
    } catch (err) {
      console.log(`• Cache recovery skipped: ${err.message}`);
    }
  } else {
    console.log("✓ Environment is clean. Safe to start Next.js dev server.");
  }
}

main().catch((err) => {
  console.error("• Fatal predev error:", err);
  process.exit(1);
});

import { describe, it, expect } from "vitest";

import { generateEmbedding, cosineSimilarity, findTopN, Candidate } from "../lib/ai/embeddings";

describe("AI Embeddings and Matching", () => {
  it("should generate deterministic fallback embedding for placeholders", async () => {
    // Save current env and force placeholder mode
    const originalKey = process.env.OPENAI_API_KEY;
    process.env.OPENAI_API_KEY = "placeholder_key";

    try {
      const text1 = "React and TypeScript developer";
      const text2 = "React and TypeScript developer";
      const text3 = "Python data scientist";

      const embedding1 = await generateEmbedding(text1);
      const embedding2 = await generateEmbedding(text2);
      const embedding3 = await generateEmbedding(text3);

      // Verify shape and type
      expect(Array.isArray(embedding1)).toBe(true);
      expect(embedding1.length).toBe(1536); // Default dimensions

      // Deterministic check
      expect(embedding1).toEqual(embedding2);
      expect(embedding1).not.toEqual(embedding3);

      // Norm validation (unit vectors)
      const magnitude = Math.sqrt(embedding1.reduce((sum, v) => sum + v * v, 0));
      expect(magnitude).toBeCloseTo(1.0, 5);
    } finally {
      process.env.OPENAI_API_KEY = originalKey;
    }
  });

  it("should calculate correct cosine similarity", () => {
    const vecA = [1, 0, 0];
    const vecB = [1, 0, 0];
    const vecC = [0, 1, 0];
    const vecD = [-1, 0, 0];

    expect(cosineSimilarity(vecA, vecB)).toBeCloseTo(1.0, 5); // Identical
    expect(cosineSimilarity(vecA, vecC)).toBeCloseTo(0.0, 5); // Orthogonal
    expect(cosineSimilarity(vecA, vecD)).toBeCloseTo(-1.0, 5); // Opposite
  });

  it("should rank candidates correctly using findTopN", () => {
    const query = [1, 0, 0];
    const candidates: Candidate[] = [
      { id: "cand1", vector: [0.1, 0.9, 0] },
      { id: "cand2", vector: [0.9, 0.1, 0] },
      { id: "cand3", vector: [0.5, 0.5, 0] },
    ];

    // Find top 2
    const results = findTopN(query, candidates, 2);

    expect(results.length).toBe(2);
    expect(results[0].id).toBe("cand2"); // Highest similarity (~0.99)
    expect(results[1].id).toBe("cand3"); // Second highest (~0.7)
  });

  it("should apply boosting function in findTopN ranking", () => {
    const query = [1, 0, 0];
    const candidates: Candidate[] = [
      { id: "cand1", vector: [0.9, 0, 0], boostVal: 0.0 }, // Similarity: 0.9 + 0 = 0.9
      { id: "cand2", vector: [0.8, 0, 0], boostVal: 0.3 }, // Similarity: 0.8 + 0.3 = 1.1
    ];

    const boostFn = (cand: Candidate, baseScore: number) => {
      return cand.boostVal || 0;
    };

    const results = findTopN(query, candidates, 2, boostFn);

    expect(results[0].id).toBe("cand2"); // cand2 has lower base score but boosted to top
  });
});

import crypto from "crypto";

import { describe, it, expect } from "vitest";

// Mock helper mimicking our parameters query parameter formatting
function buildSearchQuery(input: string): string {
  // Simulates escaping/parameterizing of search query arguments
  const escaped = input.replace(/['\"%\\]/g, "");
  return escaped;
}

// Mock helper verifying that tokens of a specific format can be decoded but fail signature check
function verifySessionToken(token: string, secret: string): boolean {
  if (!token.includes(".")) return false;
  const [header, payload, signature] = token.split(".");

  const expectedSignature = crypto
    .createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  return signature === expectedSignature;
}

describe("Automated Security & Penetration Audits", () => {
  describe("SQL Injection Safeguards", () => {
    it("should sanitize query strings and prevent SQL injection payload concatenation", () => {
      const normalInput = "ReactDeveloper";
      const sqlPayload = "' OR '1'='1";

      expect(buildSearchQuery(normalInput)).toBe("ReactDeveloper");
      expect(buildSearchQuery(sqlPayload)).toBe(" OR 1=1"); // Blocked single quotes
    });
  });

  describe("Cross-Site Scripting (XSS) String Sanitization", () => {
    it("should escape special characters to block XSS vector tags", () => {
      const maliciousScript = "<script>alert('xss')</script>";

      // Simulates standard string escaping
      const escaped = maliciousScript
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#x27;");

      expect(escaped).toBe("&lt;script&gt;alert(&#x27;xss&#x27;)&lt;/script&gt;");
    });
  });

  describe("Session JWT Signature Check", () => {
    const secret = "app_secret_123456";

    it("should accept signature matching correctly-signed JWT tokens", () => {
      const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })).toString("base64url");
      const payload = Buffer.from(JSON.stringify({ userId: "u-12", role: "STUDENT" })).toString("base64url");

      const signature = crypto
        .createHmac("sha256", secret)
        .update(`${header}.${payload}`)
        .digest("base64url");

      const token = `${header}.${payload}.${signature}`;
      expect(verifySessionToken(token, secret)).toBe(true);
    });

    it("should reject forged tokens with invalid signature", () => {
      const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })).toString("base64url");
      const payload = Buffer.from(JSON.stringify({ userId: "u-12", role: "ADMIN" })).toString("base64url"); // Forged role
      const forgedToken = `${header}.${payload}.forged_sig_here`;

      expect(verifySessionToken(forgedToken, secret)).toBe(false);
    });
  });

  describe("Privilege Escalation Check", () => {
    it("should block non-founder users from accessing founder dashboard APIs", () => {
      const roles = ["STUDENT", "CLIENT", "STARTUP", "FOUNDER"];

      const isAuthorizedForFounderHub = (role: string) => {
        return role === "FOUNDER";
      };

      expect(isAuthorizedForFounderHub("STUDENT")).toBe(false);
      expect(isAuthorizedForFounderHub("CLIENT")).toBe(false);
      expect(isAuthorizedForFounderHub("STARTUP")).toBe(false);
      expect(isAuthorizedForFounderHub("FOUNDER")).toBe(true);
    });
  });

  describe("Centralized Authorization Helpers", () => {
    it("should reject unauthorized resource access where user ID does not match resource owner", () => {
      const authenticatedUserId = "user-123";
      const resourceOwnerId = "user-999";

      const checkOwnership = (userId: string, ownerId: string) => {
        return userId === ownerId;
      };

      expect(checkOwnership(authenticatedUserId, resourceOwnerId)).toBe(false);
      expect(checkOwnership(authenticatedUserId, authenticatedUserId)).toBe(true);
    });

    it("should allow only conversation participants to access conversation details", () => {
      const userId = "user-123";
      const conversationParticipants = ["user-123", "user-456"];
      const strangerId = "user-789";

      const checkParticipant = (userId: string, participants: string[]) => {
        return participants.includes(userId);
      };

      expect(checkParticipant(userId, conversationParticipants)).toBe(true);
      expect(checkParticipant(strangerId, conversationParticipants)).toBe(false);
    });

    it("should allow only organization members to access organization updates", () => {
      const memberUserId = "user-member";
      const organizationMembers = ["user-member", "user-admin"];
      const externalUserId = "user-external";

      const checkMembership = (userId: string, members: string[]) => {
        return members.includes(userId);
      };

      expect(checkMembership(memberUserId, organizationMembers)).toBe(true);
      expect(checkMembership(externalUserId, organizationMembers)).toBe(false);
    });
  });
});

