export async function POST(req: Request) {
    try {
        const auth = await protectApi(["FOUNDER", "STUDENT"]);
        if (auth.errorResponse) return auth.errorResponse;
        const { user } = auth;
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const body = await req.json();
        const { roleTitle, difficulty } = body;

        if (!roleTitle || !difficulty) {
            return NextResponse.json({ error: "roleTitle and difficulty are required" }, { status: 400 });
        }

        const openai = getOpenAI();
        const response = await openai.chat.completions.create({
            model: getChatModel(),
            messages: [
                {
                    role: "system",
                    content: `You are a strict technical interviewer at a high-growth startup conducting a mock interview for the role of ${roleTitle}.
The candidate wants a ${difficulty} difficulty interview.
Ask the first technical question. Introduce yourself briefly (under 20 words), and then ask a challenging question appropriate for ${difficulty} difficulty level.
Ask only ONE question. Do not output anything else.`
                }
            ],
            temperature: 0.7,
            max_tokens: 150,
        });

        const firstQuestion = response.choices[0]?.message?.content?.trim() || "Let's start. Please explain what experience you have with this role.";

        const chatHistory = [
            { role: "assistant", content: firstQuestion, timestamp: new Date() }
        ];

        const interview = await prisma.mockInterview.create({
            data: {
                userId: user.id,
                roleTitle,
                difficulty,
                chatHistory: chatHistory as any,
            }
        });

        return NextResponse.json({ success: true, data: interview });
    } catch (error: any) {
        console.error("[MOCK_INTERVIEW_POST_ERROR]:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

export async function PATCH(req: Request) {
    try {
        const auth = await protectApi(["FOUNDER", "STUDENT"]);
        if (auth.errorResponse) return auth.errorResponse;
        const { user } = auth;
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const body = await req.json();
        const { interviewId, answer } = body;

        if (!interviewId || !answer) {
            return NextResponse.json({ error: "interviewId and answer are required" }, { status: 400 });
        }

        const interview = await prisma.mockInterview.findUnique({
            where: { id: interviewId, userId: user.id }
        });

        if (!interview) {
            return NextResponse.json({ error: "Interview session not found" }, { status: 404 });
        }

        const history = (interview.chatHistory as any[]) || [];

        // Append user answer
        history.push({ role: "user", content: answer, timestamp: new Date() });

        // Count how many assistant questions have been asked
        const questionCount = history.filter(m => m.role === "assistant").length;

        const openai = getOpenAI();

        if (questionCount < 5) {
            // Ask next question
            const formattedMessages = history.map(h => ({
                role: h.role as "user" | "assistant",
                content: h.content
            }));

            const response = await openai.chat.completions.create({
                model: getChatModel(),
                messages: [
                    {
                        role: "system",
                        content: `You are conducting a technical interview for the role of ${interview.roleTitle} at ${interview.difficulty} difficulty.
Ask the next question based on the conversation so far. If their previous answer was incomplete or incorrect, ask a follow-up or provide a hint, then ask the next question.
Ask ONLY one question at a time. Keep it concise.`
                    },
                    ...formattedMessages
                ],
                temperature: 0.7,
                max_tokens: 150,
            });

            const nextQuestion = response.choices[0]?.message?.content?.trim() || "Could you expand on that?";

            history.push({ role: "assistant", content: nextQuestion, timestamp: new Date() });

            await prisma.mockInterview.update({
                where: { id: interviewId },
                data: { chatHistory: history as any }
            });

            return NextResponse.json({
                success: true,
                status: "ongoing",
                nextQuestion,
                questionNumber: questionCount + 1
            });
        } else {
            // 5 questions completed! Evaluate and grade
            const formattedMessages = history.map(h => ({
                role: h.role as "user" | "assistant",
                content: h.content
            }));

            const response = await openai.chat.completions.create({
                model: getChatModel(),
                response_format: { type: "json_object" },
                messages: [
                    {
                        role: "system",
                        content: `Evaluate this mock interview transcript for the role of ${interview.roleTitle} at ${interview.difficulty} difficulty.
Return a JSON object containing:
- score: number (overall score 0-100)
- feedback: a JSON object containing:
  - technical: number (score 0-100 for technical correctness of answers)
  - communication: number (score 0-100 for clarity, explanation style, structure)
  - structure: number (score 0-100 for logical flow and approach)
  - strengths: string[] (top 3 strengths demonstrated)
  - improvements: string[] (top 3 areas for improvement)

No preamble. Return ONLY a valid JSON object.`
                    },
                    ...formattedMessages
                ],
                temperature: 0.5,
            });

            const rawContent = response.choices[0]?.message?.content || "{}";
            let parsedData;
            try {
                parsedData = JSON.parse(rawContent);
            } catch (err) {
                console.error("Failed to parse LLM grading output:", rawContent);
                parsedData = {
                    score: 70,
                    feedback: {
                        technical: 70,
                        communication: 70,
                        structure: 70,
                        strengths: ["Completed the full interview", "Good effort answering all questions"],
                        improvements: ["Provide more code syntax explanations", "Clarify architecture decisions"]
                    }
                };
            }

            const updatedInterview = await prisma.mockInterview.update({
                where: { id: interviewId },
                data: {
                    chatHistory: history as any,
                    score: parsedData.score || 70,
                    feedback: parsedData.feedback || {},
                }
            });

            return NextResponse.json({
                success: true,
                status: "completed",
                data: updatedInterview
            });
        }
    } catch (error: any) {
        console.error("[MOCK_INTERVIEW_PATCH_ERROR]:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import OpenAI from "openai";

import { protectApi } from "@/lib/auth-checks";
import prisma from "@/lib/prisma";

export const maxDuration = 60;

function getOpenAIClient(): OpenAI {
  if (!process.env.OPENAI_API_KEY) {
    throw new Error("OPENAI_API_KEY is not set");
  }
  return new OpenAI({
    apiKey: process.env.OPENAI_API_KEY,
    ...(process.env.OPENAI_API_KEY.startsWith("gsk_")
      ? { baseURL: "https://api.groq.com/openai/v1" }
      : {}),
  });
}

// ────────────────────────────────────────────────────────────────────────────
// POST /api/ai/resume-analyze
// Analyzes a resume and persists the result to the ResumeAnalysis table.
// ────────────────────────────────────────────────────────────────────────────
export async function POST(req: NextRequest) {
  try {
    const auth = await protectApi(["FOUNDER", "STUDENT", "STARTUP", "CLIENT"]);
    if (auth.errorResponse) return auth.errorResponse;

    const openai = getOpenAIClient();

    let body: { resumeText?: string };
    try {
      body = await req.json();
    } catch {
      return NextResponse.json({ error: "Invalid request body" }, { status: 400 });
    }

    const { resumeText } = body;
    if (!resumeText || typeof resumeText !== "string" || resumeText.trim().length < 50) {
      return NextResponse.json(
        { error: "resumeText is required and must be at least 50 characters" },
        { status: 400 }
      );
    }

    const model = process.env.OPENAI_API_KEY?.startsWith("gsk_")
      ? "llama-3.3-70b-versatile"
      : "gpt-4o-mini";

    const response = await openai.chat.completions.create({
      model,
      max_tokens: 1500,
      messages: [
        {
          role: "system",
          content: `You are an expert ATS (Applicant Tracking System) and senior career coach.
Analyze the resume text and return ONLY a JSON object with exactly this structure:
{
  "score": number (0-100, ATS compatibility score),
  "grade": string ("A+", "A", "B+", "B", "C+", "C", "D"),
  "strengths": string[] (3-5 specific strengths found in this resume),
  "weaknesses": string[] (3-5 specific weaknesses),
  "skills": string[] (all technical and soft skills detected),
  "missingSkills": string[] (high-demand skills absent from this resume),
  "suggestions": string[] (5-7 concrete, actionable improvement suggestions),
  "keywords": string[] (important industry keywords present),
  "experienceLevel": string ("Fresher", "Junior", "Mid-level", "Senior", "Lead"),
  "summary": string (2-sentence objective assessment),
  "section_scores": {
    "skills_match": number (0-100),
    "structure": number (0-100),
    "content_depth": number (0-100),
    "keyword_density": number (0-100)
  }
}
No preamble. No markdown. Just JSON.`,
        },
        {
          role: "user",
          content: resumeText.slice(0, 10000),
        },
      ],
    });

    const raw = response.choices[0]?.message?.content ?? "{}";
    let parsed: Record<string, unknown>;
    try {
      const clean = raw.replace(/```json|```/g, "").trim();
      parsed = JSON.parse(clean);
    } catch {
      return NextResponse.json({ error: "AI returned invalid JSON", raw }, { status: 500 });
    }

    // ── Persist the result to the database ──────────────────────────────────
    // The ResumeAnalysis model stores results per-user so users can review
    // their analysis history without re-running the AI each time.
    const wordCount = resumeText.trim().split(/\s+/).length;
    const savedAnalysis = await prisma.resumeAnalysis.create({
      data: {
        userId: auth.user!.id,
        score: typeof parsed.score === "number" ? parsed.score : 0,
        grade: typeof parsed.grade === "string" ? parsed.grade : "N/A",
        resumeSnippet: resumeText.slice(0, 200), // Store only first 200 chars for reference
        wordCount,
        result: parsed as object, // Full AI JSON stored as Prisma Json field
      },
      select: { id: true, createdAt: true },
    });

    return NextResponse.json({
      success: true,
      resume_id: savedAnalysis.id,
      data: {
        ...parsed,
        word_count: wordCount,
        processing_time_ms: Date.now(),
      },
    });
  } catch (error: unknown) {
    const err = error as {
      message?: string;
      status?: number;
    };
    console.error("[resume-analyze] error:", error);

    if (err?.message?.includes("OPENAI_API_KEY")) {
      return NextResponse.json({ error: "AI service not configured" }, { status: 503 });
    }
    if (err?.status === 401) {
      return NextResponse.json({ error: "Invalid AI API key" }, { status: 503 });
    }
    if (err?.status === 429) {
      return NextResponse.json({ error: "AI rate limit reached. Try again shortly." }, { status: 429 });
    }
    if (err?.status === 503) {
      return NextResponse.json({ error: "AI service temporarily unavailable" }, { status: 503 });
    }

    return NextResponse.json(
      { error: err?.message ?? "Unexpected server error" },
      { status: 500 }
    );
  }
}

// ────────────────────────────────────────────────────────────────────────────
// GET /api/ai/resume-analyze
// Returns the authenticated user's resume analysis history (latest 10 results).
// ────────────────────────────────────────────────────────────────────────────
export async function GET(_req: NextRequest) {
  try {
    const auth = await protectApi(["FOUNDER", "STUDENT", "STARTUP", "CLIENT"]);
    if (auth.errorResponse) return auth.errorResponse;

    const analyses = await prisma.resumeAnalysis.findMany({
      where: { userId: auth.user!.id },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: {
        id: true,
        score: true,
        grade: true,
        resumeSnippet: true,
        wordCount: true,
        result: true,
        createdAt: true,
      },
    });

    return NextResponse.json({ success: true, data: analyses });
  } catch (error) {
    console.error("[resume-analyze GET] error:", error);
    return NextResponse.json({ error: "Failed to fetch analysis history" }, { status: 500 });
  }
}

import { cookies } from "next/headers";
import { NextResponse } from "next/server";
import { z } from "zod";

import prisma from "@/lib/prisma";
import { sanitizeInput } from "@/lib/security/sanitization";
import { createClient } from "@/lib/supabase/server";
import { validateSessionUserId, isValidUUID } from "@/lib/uuid-utils";

const ApplySchema = z.object({
    gigId: z.string().uuid("Invalid Gig ID format"),
    coverLetter: z.string().max(5000, "Cover letter must be under 5000 characters").optional().nullable(),
});

export const dynamic = "force-dynamic";

export async function POST(req: Request) {
    try {
        const cookieStore = await cookies();
        const isPreview = (await cookieStore).get('admin_preview_mode')?.value === 'true';

        if (isPreview) {
            return NextResponse.json({ error: "Cannot submit applications in Preview Mode" }, { status: 403 });
        }

        // Get authenticated user
        const supabase = await createClient();
        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const userId = user.id;

        // 🛡️ UUID Guard
        try {
            validateSessionUserId(userId, "POST /api/applications/apply");
        } catch (uuidErr) {
            console.error("[P2023 Guard]", uuidErr);
            return NextResponse.json({ error: "Invalid session. Please sign out and sign in again." }, { status: 400 });
        }
        // Parse request body
        let body;
        try {
            body = await req.json();
        } catch {
            return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
        }

        const parseResult = ApplySchema.safeParse(body);
        if (!parseResult.success) {
            return NextResponse.json(
                { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        const { gigId } = parseResult.data;
        const coverLetter = parseResult.data.coverLetter ? sanitizeInput(parseResult.data.coverLetter) : null;

        // Check if gig exists and is open
        const gig = await prisma.gig.findUnique({
            where: { id: gigId },
            select: {
                id: true,
                status: true,
                posted_by: true,
            },
        });

        if (!gig) {
            return NextResponse.json({ error: "Gig not found" }, { status: 404 });
        }

        if (gig.status !== "OPEN") {
            return NextResponse.json({ error: "This gig is no longer accepting applications" }, { status: 400 });
        }

        // Check if user is the poster
        if (gig.posted_by === userId) {
            return NextResponse.json({ error: "You cannot apply to your own gig" }, { status: 400 });
        }

        // Check if user has already applied
        const existingApplication = await prisma.application.findFirst({
            where: {
                gigId,
                applicantId: userId,
            },
        });

        if (existingApplication) {
            return NextResponse.json({ error: "You have already applied to this gig" }, { status: 400 });
        }

        // Create application
        const application = await prisma.application.create({
            data: {
                gigId,
                applicantId: userId,
                coverLetter: coverLetter || null,
                status: "PENDING",
            },
            include: {
                gig: {
                    select: {
                        title: true,
                    },
                },
                applicant: {
                    select: {
                        name: true,
                        email: true,
                    },
                },
            },
        });

        return NextResponse.json({
            message: "Application submitted successfully",
            application: {
                id: application.id,
                status: application.status,
                createdAt: application.createdAt,
            },
        });
    } catch (error) {
        console.error("Error creating application:", error);
        return NextResponse.json(
            { error: "Failed to submit application" },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

import prisma from "@/lib/prisma";
import { sanitizeInput } from "@/lib/security/sanitization";
import { createClient } from "@/lib/supabase/server";

const ConversationCreateSchema = z.object({
    otherUserId: z.string().uuid("Invalid user ID format"),
    initialMessage: z.string().max(2000, "Message must be under 2000 characters").optional().nullable(),
});
import { validateSessionUserId } from "@/lib/uuid-utils";

// GET - Fetch all conversations for the current user
export async function GET(req: Request) {
    try {
        const supabase = await createClient();
        const { data: { user }, error: authError } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const userId = user.id;

        try {
            validateSessionUserId(userId, "GET /api/conversations");
        } catch (uuidErr) {
            console.error("[P2023 Guard]", uuidErr);
            return NextResponse.json({ error: "Invalid session." }, { status: 400 });
        }

        const searchParams = new URL(req.url).searchParams;
        const page = Math.max(parseInt(searchParams.get("page") || "1"), 1);
        const pageSize = Math.min(Math.max(parseInt(searchParams.get("limit") || "20"), 20), 100);
        const skip = (page - 1) * pageSize;

        // Fetch conversations where user is participant_1 or participant_2
        const [conversations, total] = await Promise.all([
            prisma.conversation.findMany({
                where: {
                    OR: [
                        { participant_1: userId },
                        { participant_2: userId },
                    ],
                },
                include: {
                    user1: {
                        select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true },
                    },
                    user2: {
                        select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true },
                    },
                    messages: {
                        orderBy: { created_at: "desc" },
                        take: 1,
                        select: {
                            id: true,
                            content: true,
                            created_at: true,
                            sender_id: true,
                            read_at: true,
                        },
                    },
                },
                orderBy: { last_message_at: "desc" },
                skip,
                take: pageSize,
            }),
            prisma.conversation.count({
                where: {
                    OR: [
                        { participant_1: userId },
                        { participant_2: userId },
                    ],
                },
            }),
        ]);

        const formattedConversations = conversations.map((conv: any) => {
            const otherUser = conv.participant_1 === userId ? conv.user2 : conv.user1;
            const lastMessage = conv.messages[0];

            return {
                id: conv.id,
                user1: conv.user1,
                user2: conv.user2,
                otherUser,
                lastMessage: lastMessage
                    ? {
                        text: lastMessage.content,
                        createdAt: lastMessage.created_at,
                        isFromMe: lastMessage.sender_id === userId,
                        isRead: !!lastMessage.read_at,
                    }
                    : null,
                last_message: conv.last_message,
                last_message_at: conv.last_message_at,
                created_at: conv.created_at,
            };
        });

        return NextResponse.json({ conversations: formattedConversations });
    } catch (error) {
        console.error("Error fetching conversations:", error);
        return NextResponse.json({ error: "Failed to fetch conversations" }, { status: 500 });
    }
}

// POST - Create a new conversation
export async function POST(request: NextRequest) {
    try {
        const supabase = await createClient();
        const { data: { user }, error: authError } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const userId = user.id;
        let body;
        try {
            body = await request.json();
        } catch {
            return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
        }

        const parseResult = ConversationCreateSchema.safeParse(body);
        if (!parseResult.success) {
            return NextResponse.json(
                { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        const { otherUserId } = parseResult.data;
        const initialMessage = parseResult.data.initialMessage ? sanitizeInput(parseResult.data.initialMessage) : undefined;

        if (otherUserId === userId) {
            return NextResponse.json({ error: "Cannot start a conversation with yourself" }, { status: 400 });
        }

        // Ensure deterministic ordering (smaller UUID first)
        const [p1, p2] = [userId, otherUserId].sort();

        // Check if conversation already exists
        const existingConversation = await prisma.conversation.findFirst({
            where: {
                OR: [
                    { participant_1: userId, participant_2: otherUserId },
                    { participant_1: otherUserId, participant_2: userId },
                ],
            },
            include: {
                user1: { select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true } },
                user2: { select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true } },
            },
        });

        if (existingConversation) {
            return NextResponse.json({ conversation: existingConversation, isNew: false });
        }

        // Create new conversation
        const conversation = await prisma.conversation.create({
            data: {
                participant_1: p1,
                participant_2: p2,
                ...(initialMessage && {
                    messages: {
                        create: {
                            content: initialMessage,
                            sender_id: userId,
                        },
                    },
                    last_message: initialMessage,
                    last_message_at: new Date(),
                }),
            },
            include: {
                user1: { select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true } },
                user2: { select: { id: true, name: true, full_name: true, email: true, image: true, avatar_url: true } },
                messages: true,
            },
        });

        return NextResponse.json({ conversation, isNew: true });
    } catch (error) {
        console.error("Error creating conversation:", error);
        return NextResponse.json({ error: "Failed to create conversation" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server"
import { z } from "zod"

import { getSession } from "@/lib/auth-checks"
import prisma from "@/lib/prisma"
import { sanitizeInput } from "@/lib/security/sanitization"

const DriveCreateSchema = z.object({
  organizationId: z.string().uuid("Invalid Organization ID format"),
  title: z.string().min(3, "Title must be at least 3 characters").max(100, "Title is too long").trim(),
  description: z.string().min(10, "Description must be at least 10 characters").max(5000, "Description is too long").trim(),
  startDate: z.string().refine(val => !isNaN(Date.parse(val)), "Invalid start date").transform(val => new Date(val)),
  endDate: z.string().refine(val => !isNaN(Date.parse(val)), "Invalid end date").transform(val => new Date(val)),
  colleges: z.array(z.string().max(100)).optional(),
});

// POST /api/employer/drives — Create a new campus drive
export async function POST(req: NextRequest) {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    let body;
    try {
      body = await req.json()
    } catch {
      return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 })
    }

    const parseResult = DriveCreateSchema.safeParse(body)
    if (!parseResult.success) {
      return NextResponse.json(
        { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { organizationId, startDate, endDate, colleges } = parseResult.data
    const title = sanitizeInput(parseResult.data.title)
    const description = sanitizeInput(parseResult.data.description)

    // Verify user is a member of the organization

    const membership = await (prisma as any).member.findFirst({
      where: { userId: user.id, organizationId },
    })
    if (!membership) {
      return NextResponse.json({ error: "Forbidden: Not a member of this organization" }, { status: 403 })
    }


    const drive = await (prisma as any).campusDrive.create({
      data: {
        organizationId,
        title,
        description,
        startDate,
        endDate,
        targetColleges: colleges || [],
        status: "UPCOMING",
      },
    })

    return NextResponse.json(drive, { status: 201 })
  } catch (error) {
    console.error("[/api/employer/drives POST]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

// GET /api/employer/drives — List drives for the user's organization
export async function GET(req: NextRequest) {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })


    const membership = await (prisma as any).member.findFirst({
      where: { userId: user.id },
      include: { organization: true },
    })

    if (!membership) {
      return NextResponse.json([])
    }


    const drives = await (prisma as any).campusDrive.findMany({
      where: { organizationId: membership.organizationId },
      orderBy: { createdAt: "desc" },
    })

    return NextResponse.json(drives)
  } catch (error) {
    console.error("[/api/employer/drives GET]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"

import { protectApi } from "@/lib/auth-checks"
import prisma from "@/lib/prisma"

// GET /api/employer/talent-search?q=react&tier=1&year=3
export async function GET(req: NextRequest) {
  try {
    const auth = await protectApi(["FOUNDER", "STARTUP", "CLIENT"])
    if (auth.errorResponse) return auth.errorResponse

    const { user } = auth;

    const { searchParams } = new URL(req.url)
    const query = searchParams.get("q") || ""
    const year = searchParams.get("year") || ""

    const candidates = await prisma.user.findMany({
      where: {
        role: "STUDENT",
        isVerified: true,
        ...(query ? {
          OR: [
            { skills: { contains: query, mode: "insensitive" } },
            { bio: { contains: query, mode: "insensitive" } },
            { careerGoal: { contains: query, mode: "insensitive" } },
          ],
        } : {}),
        ...(year ? { year } : {}),
      },
      select: {
        id: true,
        name: true,
        full_name: true,
        image: true,
        avatar_url: true,
        college: true,
        branch: true,
        year: true,
        skills: true,
        bio: true,
        isVerified: true,
        github: true,
        linkedin: true,
        portfolio: true,
        userSkills: {
          select: {
            skill: { select: { name: true, category: true, color: true } },
          },
          take: 6,
        },
        reviewsReceived: {
          select: { rating: true },
          take: 50,
        },
        gigsPosted: {
          where: { status: "COMPLETED" },
          select: { id: true },
          take: 30,
        },
        endorsementsReceived: {
          select: { id: true },
          take: 30,
        },
      },
      take: 50,
      orderBy: { createdAt: "desc" },
    })

    // Compute reputation scores
    const ranked = candidates
      .map((c: any) => {
        const avgRating =
          c.reviewsReceived.length > 0
            ? c.reviewsReceived.reduce((a: any, r: any) => a + r.rating, 0) / c.reviewsReceived.length
            : 0
        const reputationScore = Math.min(
          100,
          Math.round(c.gigsPosted.length * 15 + c.endorsementsReceived.length * 5 + avgRating * 10)
        )
        return { ...c, reputationScore, avgRating }
      })
      .sort((a: any, b: any) => b.reputationScore - a.reputationScore)

    return NextResponse.json(ranked)
  } catch (error) {
    console.error("[/api/employer/talent-search GET]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"

import { getSession } from "@/lib/auth-checks"
import {
  XP_REWARDS, computeLevel, computeSmartScore, getStreakMultiplier, BADGES
} from "@/lib/gamification"
import prisma from "@/lib/prisma"

// ── GET /api/gamification/profile ─────────────────────────────────────────────
export async function GET() {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })


    let gamif = await (prisma as any).userGamification.findUnique({
      where: { userId: user.id },
      include: {
        xpEvents: { orderBy: { createdAt: "desc" }, take: 10 },
        userBadges: {
          include: { badge: true },
          where: { isShowcased: true },
          orderBy: { earnedAt: "desc" },
        },
      },
    })

    // Auto-create on first access
    if (!gamif) {

      gamif = await (prisma as any).userGamification.create({
        data: { userId: user.id },
        include: {
          xpEvents: { take: 10 },
          userBadges: { include: { badge: true } },
        },
      })
    }

    // Compute derived fields
    const levelData = computeLevel(gamif.totalXp)
    const smartScore = computeSmartScore(
      gamif.reliabilityScore,
      gamif.executionScore,
      gamif.learningScore,
      gamif.communityScore,
    )

    // Check streak validity (missed a day = streak broken)
    let currentStreak = gamif.currentStreak
    if (gamif.lastActivityDate) {
      const last = new Date(gamif.lastActivityDate)
      const now = new Date()
      const diffDays = Math.floor((now.getTime() - last.getTime()) / (1000 * 60 * 60 * 24))
      if (diffDays > 1) currentStreak = 0
    }

    return NextResponse.json({
      ...gamif,
      currentStreak,
      smartScore,
      level: levelData.level,
      levelTitle: levelData.title,
      levelProgress: levelData.progress,
      nextLevelXp: levelData.nextMin,
      streakMultiplier: getStreakMultiplier(currentStreak),
    })
  } catch (error) {
    console.error("[GET /api/gamification/profile]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

// ── POST /api/gamification/profile (trigger XP event) ────────────────────────
export async function POST(req: NextRequest) {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const { type, metadata } = await req.json()
    if (!type || !(type in XP_REWARDS)) {
      return NextResponse.json({ error: "Invalid XP event type" }, { status: 400 })
    }

    const baseXp = XP_REWARDS[type as keyof typeof XP_REWARDS]

    // Get or create gamification record

    let gamif = await (prisma as any).userGamification.findUnique({ where: { userId: user.id } })
    if (!gamif) {

      gamif = await (prisma as any).userGamification.create({ data: { userId: user.id } })
    }

    // Compute streak & multiplier
    const now = new Date()
    let newStreak = gamif.currentStreak
    if (gamif.lastActivityDate) {
      const diffDays = Math.floor((now.getTime() - new Date(gamif.lastActivityDate).getTime()) / (1000 * 60 * 60 * 24))
      if (diffDays === 0) newStreak = gamif.currentStreak       // same day — no change
      else if (diffDays === 1) newStreak = gamif.currentStreak + 1 // next day — extend
      else newStreak = 1                                         // gap — reset
    } else {
      newStreak = 1
    }

    const multiplier = getStreakMultiplier(newStreak)
    const finalXp = Math.round(baseXp * multiplier)

    const newTotal = gamif.totalXp + finalXp
    const levelData = computeLevel(newTotal)

    // Update gamification record + log XP event

    const [updated] = await (prisma as any).$transaction([

      (prisma as any).userGamification.update({
        where: { userId: user.id },
        data: {
          totalXp: newTotal,
          level: levelData.level,
          levelTitle: levelData.title,
          currentStreak: newStreak,
          longestStreak: Math.max(gamif.longestStreak, newStreak),
          lastActivityDate: now,
          smartScore: computeSmartScore(
            gamif.reliabilityScore,
            type === "GIG_COMPLETED" ? Math.min(100, gamif.executionScore + 5) : gamif.executionScore,
            type === "SKILL_VERIFIED" ? Math.min(100, gamif.learningScore + 10) : gamif.learningScore,
            gamif.communityScore,
          ),
          ...(type === "GIG_COMPLETED" && { gigsCompleted: gamif.gigsCompleted + 1 }),
          ...(type === "GIG_COMPLETED" && !gamif.firstGigAt && { firstGigAt: now }),
        },
      }),

      (prisma as any).xpEvent.create({
        data: {
          gamificationId: gamif.id,
          type,
          xpAwarded: finalXp,
          multiplier,
          description: buildDescription(type, multiplier, newStreak),
          metadata: metadata || null,
        },
      }),
    ])

    // Badge checks — fire-and-forget (don't block response)
    checkAndAwardBadges(gamif.id, user.id, { ...gamif, totalXp: newTotal, gigsCompleted: gamif.gigsCompleted + (type === "GIG_COMPLETED" ? 1 : 0), currentStreak: newStreak })
      .catch(() => {/* non-blocking */})

    return NextResponse.json({ xpAwarded: finalXp, multiplier, newTotal, level: levelData, streakDays: newStreak })
  } catch (error) {
    console.error("[POST /api/gamification/profile]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

function buildDescription(type: string, multiplier: number, streak: number): string {
  const streakNote = multiplier > 1 ? ` (${streak}-day streak ${multiplier}×)` : ""
  const map: Record<string, string> = {
    GIG_COMPLETED: `Gig completed${streakNote}`,
    FIRST_GIG: "First gig bonus!",
    REVIEW_RECEIVED_5STAR: `5-star review received${streakNote}`,
    REVIEW_RECEIVED_4STAR: "4-star review received",
    SKILL_VERIFIED: "Skill verified",
    PROFILE_COMPLETE: "Profile completed",
    STREAK_7: "7-day streak bonus!",
    STREAK_30: "30-day streak bonus!",
    STREAK_100: "100-day streak — LEGENDARY!",
    REFERRAL_SIGNUP: "Referral bonus",
    BADGE_EARNED: "Badge earned",
  }
  return map[type] || type
}

async function checkAndAwardBadges(gamifId: string, userId: string, state: {
  gigsCompleted: number
  totalEarned: number
  currentStreak: number
}) {
  for (const badge of BADGES) {
    const req = badge.requirement as { type: string; value: number }
    let earned = false

    if (req.type === "gig_count" && state.gigsCompleted >= req.value) earned = true
    else if (req.type === "earned_inr" && state.totalEarned >= req.value) earned = true
    else if (req.type === "streak_days" && state.currentStreak >= req.value) earned = true

    if (!earned) continue

    try {

      const badgeRecord = await (prisma as any).badge.findUnique({ where: { slug: badge.slug } })
      if (!badgeRecord) continue


      await (prisma as any).userBadge.upsert({
        where: { userId_badgeId: { userId, badgeId: badgeRecord.id } },
        update: {},
        create: { userId, badgeId: badgeRecord.id, gamificationId: gamifId },
      })
    } catch {
      // Already exists or other non-critical error — skip
    }
  }
}

import { Prisma } from "@prisma/client";
import { NextResponse } from "next/server";
import { z } from "zod";

import { filterAndRankGigs } from "@/lib/ai/filterAndRank";
import { moderateGig } from "@/lib/ai/moderator";
import prisma from "@/lib/prisma";
import { generalApiLimiter } from "@/lib/rate-limit";
import { sanitizeInput } from "@/lib/security/sanitization";
import { createClient } from "@/lib/supabase/server";
import { validateSessionUserId } from "@/lib/uuid-utils";


export const dynamic = "force-dynamic";

// Input Validation Schemas
const GigCreateSchema = z.object({
    title: z.string().min(3, "Title must be at least 3 characters").max(100, "Title cannot exceed 100 characters").trim(),
    description: z.string().min(10, "Description must be at least 10 characters").max(2000, "Description cannot exceed 2000 characters").trim(),
    budget: z.coerce.number().positive("Budget must be a positive number").max(1000000, "Budget cannot exceed 1,000,000"),
    deadline: z.string().nullish().transform(val => {
        if (!val || val.trim() === "") return null;
        const d = new Date(val);
        return isNaN(d.getTime()) ? null : d;
    }),
});

const GigPatchSchema = z.object({
    id: z.string().uuid("Invalid gig ID format"),
    status: z.string().min(1, "Status cannot be empty").max(20, "Status is too long").trim(),
});

const GigQuerySchema = z.object({
    q: z.string().catch(""),
    category: z.string().catch(""),
    minBudget: z.coerce.number().int().nonnegative().catch(0),
    maxBudget: z.coerce.number().int().positive().catch(999999),
    sort: z.enum(["newest", "budget-high", "budget-low", "deadline", "relevant"]).catch("newest"),
    page: z.coerce.number().int().positive().catch(1),
});

//////////////////////////////////////////////////////
// GET GIGS
//////////////////////////////////////////////////////

export async function GET(req: Request) {
    try {
        const supabase = await createClient();
        const { data: { user }, error } =
            await supabase.auth.getUser();

        if (error || !user) {
            return NextResponse.json({
                gigs: [],
                matched: 0,
            });
        }

        //////////////////////////////////////////////////////
        // AUTO CREATE USER IF MISSING
        //////////////////////////////////////////////////////

        // ðŸ›¡ï¸ UUID Guard: Supabase can return a session with a non-UUID id in some edge-cases
        try {
            validateSessionUserId(user.id, "GET /api/gigs");
        } catch {
            return NextResponse.json({ gigs: [], matched: 0 });
        }

        let dbUser = await prisma.user.findUnique({
            where: { id: user.id },
        });

        if (!dbUser) {
            dbUser = await prisma.user.create({
                data: {
                    id: user.id,
                    email: user.email!,
                },
            });
        }

        if (!dbUser.latitude || !dbUser.longitude) {
            return NextResponse.json({
                gigs: [],
                matched: 0,
            });
        }

        const searchParams = new URL(req.url).searchParams;
        const queryParams = Object.fromEntries(searchParams.entries());
        const parsed = GigQuerySchema.parse(queryParams);
        const { q: query, category, minBudget, maxBudget, sort, page } = parsed;

        let orderByClause: Prisma.GigOrderByWithRelationInput = { createdAt: "desc" };
        if (sort === "budget-high") orderByClause = { budget: "desc" };
        else if (sort === "budget-low") orderByClause = { budget: "asc" };
        else if (sort === "deadline") orderByClause = { deadline: "asc" };
        else if (sort === "newest") orderByClause = { createdAt: "desc" };

        const pageSize = Math.min(Math.max(parseInt(searchParams.get("limit") || "12"), 20), 100);
        const skip = (page - 1) * pageSize;
        const SEARCH_LIMIT = 500;

        const baseWhere = {
            status: "OPEN",
            budget: {
                gte: minBudget,
                lte: maxBudget,
            },
            ...(category && category !== "All" && category.toLowerCase() !== "general" ? {
                tags: {
                    contains: category,
                    mode: "insensitive" as const
                }
            } : {}),
            ...(query ? {
                OR: [
                    { title: { contains: query, mode: "insensitive" as const } },
                    { description: { contains: query, mode: "insensitive" as const } },
                    { tags: { contains: query, mode: "insensitive" as const } },
                    { poster: { name: { contains: query, mode: "insensitive" as const } } }
                ]
            } : {})
        };

        const include = {
            poster: { select: { id: true, name: true, image: true } },
            _count: { select: { applications: true } }
        };

        let gigs: any[] = [];
        let total = 0;

        if (sort === "relevant") {
            const rawGigs = await prisma.gig.findMany({
                where: baseWhere,
                include,
                orderBy: orderByClause,
                take: SEARCH_LIMIT,
            });

            const ranked = filterAndRankGigs({
                user: dbUser,
                gigs: rawGigs,
            });

            total = ranked.length;
            gigs = ranked.slice(skip, skip + pageSize);
        } else {
            const [items, count] = await Promise.all([
                prisma.gig.findMany({
                    where: baseWhere,
                    include,
                    orderBy: orderByClause,
                    skip,
                    take: pageSize,
                }),
                prisma.gig.count({ where: baseWhere }),
            ]);
            gigs = items;
            total = count;
        }

        return NextResponse.json({
            gigs,
            page,
            pageSize,
            totalItems: total,
            totalPages: Math.ceil(total / pageSize),
            hasNextPage: skip + gigs.length < total,
            hasPreviousPage: page > 1,
        });
    } catch (error: unknown) {
        const msg = error instanceof Error ? error.message : "Internal server error";
        console.error("[GIGS_GET_ERROR]:", error);
        return NextResponse.json(
            { gigs: [], error: msg },
            { status: 500 }
        );
    }
}

