"use client";

import { motion, AnimatePresence } from "framer-motion";
import { 
    FileText, Search, Star, AlertCircle, CheckCircle2, 
    Loader2, UploadCloud, BrainCircuit, X, Sparkles, TrendingUp,
    ChevronRight, Zap
} from "lucide-react";
import { useState, useRef, useEffect } from "react";
import { toast } from "react-hot-toast";

import { Badge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "@/components/ui/Card";
import { cn } from "@/lib/utils";

type SectionScores = {
    skills_match: number;
    structure: number;
    content_depth: number;
    keyword_density: number;
};

type AnalysisResult = {
    resume_id?: string;
    score?: number;
    grade?: string;
    skills?: string[];
    missingSkills?: string[];
    suggestions?: string[];
    section_scores?: SectionScores;
    word_count?: number;
    processing_time_ms?: number;
    strengths?: string[];
    weaknesses?: string[];
};

type HistoryEntry = {
    id: string;
    score: number;
    grade: string;
    resumeSnippet: string | null;
    wordCount: number;
    result: AnalysisResult | null;
    createdAt: string;
};

const RESUME_ANALYZE_ENDPOINT = "/api/ai/resume-analyzer";

export default function ResumeAnalyzerPage() {
    const [resumeText, setResumeText] = useState("");
    const [file, setFile] = useState<File | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const [isLoading, setIsLoading] = useState(false);
    const [isParsing, setIsParsing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [result, setResult] = useState<AnalysisResult | null>(null);

    // ── History ──────────────────────────────────────────────────────────────
    const [history, setHistory] = useState<HistoryEntry[]>([]);
    const [loadingHistory, setLoadingHistory] = useState(true);

    useEffect(() => {
        if (error) {
            toast.error(error || "Analysis failed. Backend might be busy.");
        }
    }, [error]);

    // Load analysis history on mount
    useEffect(() => {
        fetch("/api/ai/resume-analyze")
            .then(r => r.ok ? r.json() : Promise.reject())
            .then(d => setHistory(d.data ?? []))
            .catch(() => setHistory([]))
            .finally(() => setLoadingHistory(false));
    }, []);

    // Restore a previous result from history
    const restoreFromHistory = (entry: HistoryEntry) => {
        if (entry.result) {
            setResult({ ...entry.result, resume_id: entry.id });
            toast.success(`Restored analysis from ${new Date(entry.createdAt).toLocaleDateString()}`);
        }
    };

    const processFile = async (selectedFile: File) => {
        setFile(selectedFile);
        setResumeText("");
        setIsParsing(true);
        setError(null);

        try {
            const formData = new FormData();
            formData.append("file", selectedFile);

            const res = await fetch("/api/ai/parse-file", {
                method: "POST",
                body: formData,
            });

            if (!res.ok) {
                const err = await res.json().catch(() => ({}));
                throw new Error(err.error ?? "Failed to read file");
            }

            const data = await res.json();
            setResumeText(data.text);
            toast.success(`Extracted ${data.text.length} characters from ${selectedFile.name}`);
        } catch (err: any) {
            console.error("processFile error:", err);
            setError(err.message ?? "Failed to parse resume");
            setFile(null);
        } finally {
            setIsParsing(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            const validTypes = ["application/pdf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "text/plain"];
            const isTxt = selectedFile.name.endsWith(".txt");

            if (!validTypes.includes(selectedFile.type) && !isTxt) {
                toast.error("Please upload a PDF, DOCX, or TXT file.");
                return;
            }
            processFile(selectedFile);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const droppedFile = e.dataTransfer.files?.[0];
        if (droppedFile) {
            processFile(droppedFile);
        }
    };

    const handleAnalyze = async () => {
      if (!resumeText || resumeText.trim().length === 0) {
        setError("Please upload your resume or paste its text first.");
        return;
      }

      try {
        setIsLoading(true);
        setError(null);

        const response = await fetch("/api/ai/resume-analyze", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ resumeText: resumeText.slice(0, 10000) }),
        });

        if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          throw new Error(errData?.error ?? `Server error: ${response.status}`);
        }

        const json = await response.json();
        setResult(json.data);

        // Prepend to local history so users see it immediately without a reload
        if (json.resume_id) {
          const newEntry: HistoryEntry = {
            id: json.resume_id,
            score: json.data?.score ?? 0,
            grade: json.data?.grade ?? "N/A",
            resumeSnippet: resumeText.slice(0, 200),
            wordCount: json.data?.word_count ?? 0,
            result: json.data,
            createdAt: new Date().toISOString(),
          };
          setHistory(prev => [newEntry, ...prev].slice(0, 10));
        }
      } catch (err: any) {
        console.error("handleAnalyze error:", err);

        // Show specific error message to user
        if (err.message.includes("API key")) {
          setError("AI service is not configured. Contact support.");
        } else if (err.message.includes("rate limit")) {
          setError("Too many requests. Please wait a moment.");
        } else if (err.message.includes("502") || 
                   err.message.includes("Bad Gateway")) {
          setError("AI service is temporarily unavailable. Please try again in a few seconds.");
        } else {
          setError(err.message ?? "Something went wrong.");
        }
      } finally {
        setIsLoading(false);
      }
    };

    const hasResult = result && result.score !== undefined;

    return (
        <div className="max-w-7xl mx-auto space-y-12 pb-24 p-4 md:p-10 min-h-screen">
            {/* Header section with gradient */}
            <header className="relative p-4 md:p-12 rounded-5xl overflow-hidden bg-[#0F172A] border border-white/5 shadow-3xl">
              <div className="absolute top-0 right-0 w-80 h-80 bg-blue-500/20 blur-[100px] rounded-full pointer-events-none z-0" />
              <div className="absolute bottom-0 left-0 w-60 h-60 bg-purple-500/20 blur-[80px] rounded-full pointer-events-none z-0" />

              <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-10">
                <div className="text-center md:text-left">
                  <motion.div 
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
