"use client"

import { motion, AnimatePresence } from "framer-motion"
import { Bell, CheckCheck, Trash2 } from "lucide-react"
import { useRouter } from "next/navigation"
import { useState, useRef, useEffect } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/Button"
import { createClient } from "@/lib/supabase/client"

interface NotificationsPopoverProps {
    isOpen?: boolean
    onOpenChange?: (open: boolean) => void
}

interface Notification {
    id: string;
    title: string;
    message: string;
    createdAt: string;
    isRead: boolean;
    link?: string;
    type: string;
}

function formatTime(dateString: string) {
    const date = new Date(dateString);
    const now = new Date();
    const diff = (now.getTime() - date.getTime()) / 1000; // seconds
    if (diff < 60) return 'Just now';
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return `${Math.floor(diff / 86400)}d ago`;
}

export default function NotificationsPopover({
    isOpen = false,
    onOpenChange,
}: NotificationsPopoverProps) {

    const [notifications, setNotifications] = useState<Notification[]>([])
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const [userId, setUserId] = useState<string | null>(null)
    const popoverRef = useRef<HTMLDivElement>(null)
    const router = useRouter()

    const fetchNotifications = async () => {
        try {
            const res = await fetch("/api/notifications");
            if (res.ok) {
                const data = await res.json();
                setNotifications(data.notifications || []);
            }
        } catch (error) {
            console.error("Failed to fetch notifications", error);
        }
    }

    // Initial setup and Realtime (Requirement 5.B)
    useEffect(() => {
        const supabase = createClient();

        async function setup() {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                setUserId(user.id);
                fetchNotifications();

                let retryCount = 0;
                const MAX_RETRIES = 5;

                // Listen for REAL-TIME database changes (Requirement 5)
                const channel = supabase
                    .channel(`user-notifications-${user.id}`)
                    .on(
                        'postgres_changes',
                        {
                            event: 'INSERT',
                            schema: 'public',
                            table: 'Notification',
                            filter: `userId=eq.${user.id}`
                        },
                        (payload: { new: unknown }) => {
                            console.log('New notification received!', payload);
                            setNotifications(prev => [payload.new as Notification, ...prev]);
                        }
                    )

                const subscribeWithRetry = () => {
                    channel.subscribe((status, err) => {
                        if (status === 'SUBSCRIBED') {
                            retryCount = 0;
                        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
                            if (retryCount < MAX_RETRIES) {
                                retryCount++;
                                setTimeout(() => {
                                    supabase.removeChannel(channel);
                                    subscribeWithRetry();
                                }, Math.min(1000 * Math.pow(2, retryCount), 10000));
                            }
                        }
                    });
                };

                subscribeWithRetry();

                return () => {
                    supabase.removeChannel(channel);
                }
            }

        }

        setup();
    }, []);

    // Close on outside click
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (
                popoverRef.current &&
                !popoverRef.current.contains(event.target as Node)
            ) {
                onOpenChange?.(false)
            }
        }

        document.addEventListener("mousedown", handleClickOutside)
        return () =>
            document.removeEventListener("mousedown", handleClickOutside)
    }, [onOpenChange])

    const unreadCount = notifications.filter(n => !n.isRead).length

    const markAsRead = async (id: string, link?: string) => {
        // Optimistic update
        setNotifications(prev =>
            prev.map(n =>
                n.id === id ? { ...n, isRead: true } : n
            )
        )

        try {
            await fetch("/api/notifications", {
                method: "PATCH",
                body: JSON.stringify({ id })
            });

            if (link) {
                onOpenChange?.(false);
                router.push(link);
            }
        } catch (e) {
            console.error("Failed to mark read", e);
        }
    }

    const markAllAsRead = async () => {
        if (unreadCount === 0) return

        setNotifications(prev =>
            prev.map(n => ({ ...n, isRead: true }))
        )

        try {
            await fetch("/api/notifications", {
                method: "PATCH",
                body: JSON.stringify({ id: "all" })
            });
            toast.success("All notifications marked as read")
        } catch (e) {
            console.error(e);
        }
    }

    const clearAll = () => {
        // In real app, might want DELETE endpoint
        setNotifications([]);
        toast.success("Notifications cleared");
    }

    return (
        <div className="relative" ref={popoverRef}>

            {/* 🔔 Bell Button */}
            <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => onOpenChange?.(!isOpen)}
                className={`relative p-2.5 rounded-full transition-all duration-300 ${isOpen ? 'bg-blue-50 text-blue-600' : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900' }`}
            >
                <Bell size={20} />

                {unreadCount > 0 && (
                    <span className="absolute -top-1 -right-1 flex h-3 w-3">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-red-500"></span>
                    </span>
                )}
            </motion.button>

            {/* 📦 Popover */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 8 }}
                        className="absolute right-0 mt-3 w-[360px] bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-800 overflow-hidden z-50"
                    >

                        {/* Header */}
                        <div className="px-4 py-3 border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-800/50">
                            <h3 className="font-bold text-foreground">
                                Notifications
                            </h3>

                            <div className="flex gap-2">
                                {unreadCount > 0 && (
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={markAllAsRead}
                                        className="h-8 w-8 p-0"
                                        title="Mark all as read"
                                    >
                                        <CheckCheck size={14} />
                                    </Button>
                                )}

                                {notifications.length > 0 && (
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={clearAll}
                                        className="h-8 w-8 p-0 text-red-500 hover:text-red-600"
                                        title="Clear all"
                                    >
                                        <Trash2 size={14} />
                                    </Button>
                                )}
                            </div>
                        </div>

                        {/* List */}
                        <div className="max-h-[320px] overflow-y-auto">

                            {notifications.length === 0 ? (
                                <div className="p-8 text-slate-500 flex flex-col items-center gap-2">
                                    <Bell size={24} className="opacity-20" />
                                    <span>No notifications yet</span>
                                </div>
                            ) : (
                                notifications.map(n => (
                                    <div
                                        key={n.id}
                                        onClick={() => markAsRead(n.id, n.link)}
                                        className={`p-4 border-slate-50 dark:border-slate-800 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${!n.isRead ? "bg-blue-50/50 dark:bg-blue-900/10" : ""}`}
                                    >
                                        <div className="flex justify-between items-start gap-2">
                                            <h4 className={`${!n.isRead ? "font-bold" : "font-semibold text-slate-600 dark:text-slate-400"}`}>
                                                {n.title}
                                            </h4>
                                            <span className="text-slate-400 whitespace-nowrap pt-1">
                                                {formatTime(n.createdAt)}
                                            </span>
                                        </div>

                                        <p className="text-slate-500 dark:text-slate-400 mt-1 line-clamp-2 leading-relaxed">
                                            {n.message}
                                        </p>
                                    </div>
                                ))
                            )}
                        </div>

                        {/* Footer */}
                        <div className="p-2 border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-800/50">
                            <Button
                                variant="ghost"
                                onClick={() => router.push("/dashboard/student/messages")}
                                className="w-full text-xs font-semibold h-8"
                            >
                                View All Messages
                            </Button>
                        </div>

                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    )
}

'use client';

import { Bot, Send, X, Minimize2, Maximize2, Sparkles } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';

interface Message {
  role: 'user' | 'assistant';
  content: string;
  id: string;
}

interface ChatContext {
  gigTitle?: string;
  gigDescription?: string;
  gigSkills?: string;
  gigBudget?: number;
  studentSkills?: string;
  studentName?: string;
  mode: 'gig-help' | 'career-advice' | 'general';
}

interface AIChatWidgetProps {
  context?: Partial<ChatContext>;
  initialMessage?: string;
  className?: string;
}

const QUICK_PROMPTS = [
  'Write my cover letter',
  'What skills should I highlight?',
  'How do I estimate the timeline?',
  'Help me negotiate the budget',
];

export function AIChatWidget({ context, initialMessage, className }: AIChatWidgetProps) {
  const [open, setOpen] = useState(false);
  const [minimized, setMinimized] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: initialMessage || "Hi! I'm your CampusConnect AI assistant. I can help you write a cover letter, understand gig requirements, estimate timelines, or plan your career. What would you like help with?",
    }
  ]);
  const [input, setInput] = useState('');
  const [streaming, setStreaming] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (text?: string) => {
    const userMessage = (text || input).trim();
    if (!userMessage || streaming) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: userMessage,
    };

    const assistantMsgId = crypto.randomUUID();
    const assistantMsg: Message = {
      id: assistantMsgId,
      role: 'assistant',
      content: '',
    };

    setMessages(prev => [...prev, userMsg, assistantMsg]);
    setInput('');
    setStreaming(true);

    try {
      const chatContext: ChatContext = {
        mode: context?.gigTitle ? 'gig-help' : 'career-advice',
        ...context,
      };

      const res = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [...messages, userMsg].map(m => ({ role: m.role, content: m.content })),
          context: chatContext,
        }),
      });

      if (!res.ok) throw new Error(await res.text());

      const reader = res.body!.getReader();
      const decoder = new TextDecoder();
      let fullContent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n').filter(Boolean);

        for (const line of lines) {
          if (line.startsWith('0:')) {
            try {
              const text = JSON.parse(line.slice(2));
              fullContent += text;
              setMessages(prev =>
                prev.map(m =>
                  m.id === assistantMsgId ? { ...m, content: fullContent } : m
                )
              );
            } catch {}
          }
        }
      }
    } catch (err: any) {
      setMessages(prev =>
        prev.map(m =>
          m.id === assistantMsgId
            ? { ...m, content: 'Sorry, something went wrong. Please try again.' }
            : m
        )
      );
    } finally {
      setStreaming(false);
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className={`flex items-center gap-2 px-4 py-2.5 bg-linear-to-r from-amber-500 to-orange-500 font-bold rounded-xl shadow-lg hover:shadow-amber-500/20 hover:scale-105 transition-all text-sm ${className}`}
      >
        <Bot className="w-4 h-4" />
        AI Assistant
      </button>
    );
  }

  return (
    <div className={`fixed bottom-6 right-6 z-50 w-[380px] ${className}`}>
      <div className="bg-[#0e0e12] border border-white/10 rounded-2xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-white/10 bg-linear-to-r from-amber-500/10 to-orange-500/10">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-(--accent)/20 flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-amber-400" />
            </div>
            <div>
              <p className="text-sm font-black">CampusConnect AI</p>
              <p className="text-slate-500">
                {streaming ? (
                  <span className="text-amber-400 animate-pulse">Typing...</span>
                ) : 'Ask me anything'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setMinimized(!minimized)}
              className="p-1.5 rounded-lg hover:bg-white/10 transition-colors text-slate-400"
            >
              {minimized ? <Maximize2 className="w-3.5 h-3.5" /> : <Minimize2 className="w-3.5 h-3.5" />}
            </button>
            <button
              onClick={() => setOpen(false)}
              className="p-1.5 hover:bg-white/10 rounded-lg text-slate-400 transition-colors shrink-0"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        {!minimized && (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3 max-h-[360px] min-h-[200px]">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  {msg.role === 'assistant' && (
                    <div className="w-6 h-6 rounded-full bg-(--accent)/20 flex items-center justify-center shrink-0 mt-0.5 mr-2">
                      <Bot className="w-3 h-3 text-amber-400" />
                    </div>
                  )}
                  <div className={`p-3 max-w-[85%] ${msg.role === 'user' ? 'bg-linear-to-r from-orange-500 to-amber-500 ml-auto' : 'bg-white/10 border border-white/5 text-slate-200 rounded-tl-[4px]'}`}>
                    {msg.content || (
                      <span className="flex gap-1 items-center py-1">
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                      </span>
                    )}
                  </div>
                </div>
              ))}
              <div ref={bottomRef} />
            </div>

            {/* Quick Prompts */}
            {messages.length <= 1 && (
              <div className="px-4 pb-2 flex flex-wrap gap-1.5">
                {QUICK_PROMPTS.map((p) => (
                  <button
                    key={p}
                    onClick={() => sendMessage(p)}
                    className="px-3 py-1.5 bg-(--surface-2) hover:bg-white/10 border border-white/10 rounded-full text-slate-400 hover:text-white transition-all"
                  >
                    {p}
                  </button>
                ))}
              </div>
            )}

            {/* Input */}
            <div className="p-3 border-white/10">
              <div className="flex gap-2 items-end bg-(--surface-2) rounded-xl border border-white/10 px-3 py-2 focus-within:border-amber-500/30 transition-colors">
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Ask anything about this gig..."
                  rows={1}
                  className="flex-1 bg-transparent text-slate-200 focus:outline-none resize-none placeholder:text-slate-600 max-h-24"
                  style={{ fieldSizing: 'content' } as any}
                />
                <button
                  onClick={() => sendMessage()}
                  disabled={!input.trim() || streaming}
                  className="w-10 h-10 rounded-xl bg-(--primary) hover:bg-orange-600 text-white flex items-center justify-center shrink-0 disabled:opacity-50 transition-colors shadow-lg"
                >
                  <Send className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

'use client';

