                     </div>
                     <ArrowRight className="w-4 h-4 text-orange-400 opacity-0 -translate-x-4 group-hover:opacity-100 group-hover:translate-x-0 transition-all" />
                  </div>
                </div>
            </Link>
          );
        }

        return null;
      })}
    </div>
  );
}

