                    }`}
                  >
                    {t}
                  </button>
                ))}
              </div>
            </div>

            {/* Year */}
            <div>
              <label className="text-xs text-slate-500 font-bold uppercase tracking-wider mb-2 block">Year</label>
              <div className="flex flex-wrap gap-2">
                {YEAR_OPTIONS.slice(0, 4).map((y) => (
                  <button
                    key={y}
