const BOOT_LOGS = [
    { text: "$ init --cluster=india --verbose", type: "cmd" },
    { text: "[OK] Core service layer booted", type: "success" },
    { text: "[OK] Hyperspatial matching index loaded (r = 5km)", type: "success" },
